def canConvertString(s: str, t: str, k: int) -> bool:
    if len(s) != len(t):
        return False

    # Calculate the difference in shifts needed for each character
    shifts = [0] * 26
    for i in range(len(s)):
        diff = (ord(t[i]) - ord(s[i])) % 26
        if diff != 0:
            shifts[diff] += 1

    # Check if we can accommodate all shifts within k moves
    for i in range(1, 26):
        if shifts[i] > (k // 26) + (1 if i <= k % 26 else 0):
            return False

    return True
